import collections


def stream_transform(source, transform, max_buffer_size=4, backpressure_callback=None):
    """Transform a source stream in bounded chunks.

    The buggy implementation materializes the entire source before yielding.
    """
    # BUG: loads the whole input generator into memory before yielding.
    data = list(source)
    buffer = []
    for item in data:
        buffer.append(item)
        if len(buffer) >= max_buffer_size:
            if backpressure_callback is not None:
                backpressure_callback()
            for buffered_item in buffer:
                yield transform(buffered_item)
            buffer.clear()
    for buffered_item in buffer:
        yield transform(buffered_item)


def aggregate_chunks(chunks, delimiter="\n", chunk_size=8):
    """Aggregate chunks into records.

    The buggy implementation slices fixed-size pieces and can split records.
    """
    buffer = ""
    for chunk in chunks:
        buffer += chunk
        # BUG: truncates at an arbitrary fixed size instead of delimiter.
        while len(buffer) >= chunk_size:
            yield buffer[:chunk_size]
            buffer = buffer[chunk_size:]
    if buffer:
        yield buffer

