import unittest
from pipeline import stream_transform, aggregate_chunks


class TestPipeline(unittest.TestCase):
    def test_stream_transform_does_not_materialize_entire_source(self):
        consumed = []

        def source():
            for value in range(1000):
                consumed.append(value)
                yield value

        transformed = list(stream_transform(source(), lambda x: x * 2, max_buffer_size=4))
        self.assertEqual(transformed, [x * 2 for x in range(1000)])
        self.assertEqual(len(consumed), 1000)

    def test_backpressure_callback_is_triggered(self):
        calls = []

        def source():
            for value in range(10):
                yield value

        result = list(
            stream_transform(
                source(),
                lambda x: x,
                max_buffer_size=3,
                backpressure_callback=lambda: calls.append(1),
            )
        )
        self.assertEqual(result, list(range(10)))
        self.assertEqual(len(calls), 3)

    def test_aggregate_chunks_respects_delimiters(self):
        chunks = ["hel", "lo\nwor", "ld\n"]
        records = list(aggregate_chunks(chunks, delimiter="\n"))
        self.assertEqual(records, ["hello", "world"])


if __name__ == "__main__":
    unittest.main()
